import{_ as p,a0 as l,w as o,s as r,I as n,x as t,a1 as a,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160425 How to Use Awk to Print Fields and Columns in File","title":"如何使用 Awk 打印文件中的字段和列","tag":"201607","desc":""},"relativePath":"201607/20160425 How to Use Awk to Print Fields and Columns in File.md","filePath":"[post].md"}'),u={name:"201607/20160425 How to Use Awk to Print Fields and Columns in File.md"};function k(m,s,h,g,w,c){const i=l("Link");return o(),r("div",null,[s[19]||(s[19]=n("h1",{id:"如何使用-awk-打印文件中的字段和列",tabindex:"-1"},[t("如何使用 Awk 打印文件中的字段和列 "),n("a",{class:"header-anchor",href:"#如何使用-awk-打印文件中的字段和列","aria-label":"Permalink to “如何使用 Awk 打印文件中的字段和列”"},"​")],-1)),n("p",null,[s[1]||(s[1]=t("在 ",-1)),a(i,{href:"http://www.tecmint.com/tag/awk-command/"},{default:e(()=>[...s[0]||(s[0]=[t("Linux Awk 命令系列介绍",-1)])]),_:1}),s[2]||(s[2]=t(" 的这部分，我们来看一下 awk 最重要的功能之一，字段编辑。",-1))]),s[20]||(s[20]=n("p",null,"首先我们要知道 Awk 会自动把输入的行切分为字段，字段可以定义为是一些字符集，这些字符集和其它字段被内部字段分隔符分离。",-1)),s[21]||(s[21]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Print-Fields-and-Columns.png",alt:""})],-1)),s[22]||(s[22]=n("blockquote",null,[n("p",null,"Awk 输出字段和列")],-1)),n("p",null,[s[4]||(s[4]=t("如果你熟悉 Unix/Linux 或者懂得 ",-1)),a(i,{href:"http://www.tecmint.com/category/bash-shell/"},{default:e(()=>[...s[3]||(s[3]=[t("bash shell 编程",-1)])]),_:1}),s[5]||(s[5]=t("，那么你也应该知道内部字段分隔符（IFS）变量。Awk 默认的 IFS 是 tab 和空格。",-1))]),s[23]||(s[23]=d(`<p>Awk 字段切分的工作原理如下：当获得一行输入时，根据定义的 IFS，第一个字符集是字段一，用 $1 表示，第二个字符集是字段二，用 $2 表示，第三个字符集是字段三，用 $3 表示，以此类推直到最后一个字符集。</p><p>为了更好的理解 Awk 的字段编辑，让我们来看看下面的例子：</p><p><strong>事例 1:</strong>： 我创建了一个名为 tecmintinfo.txt 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi tecmintinfo.txt</span></span>
<span class="line"><span># cat tecmintinfo.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Create-File-in-Linux.png" alt=""></p><blockquote><p>在 Linux 中创建文件</p></blockquote><p>然后在命令行中使用以下命令打印 tecmintinfo.txt 文件中的第一、第二和第三个字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1 $2 $3 }&#39; tecmintinfo.txt</span></span>
<span class="line"><span>TecMint.comisthe</span></span></code></pre></div><p>从上面的输出中你可以看到，三个字段中的第一个是按照定义的 IFS，也就是空格，打印的。</p><ul><li>字段一 “TecMint.com” 使用 $1 访问。</li><li>字段二 “is” 通过 $2 访问。</li><li>字段三 “the” 通过 $3 访问。</li></ul><p>如果你注意打印的输出，可以看到字段值之间并没有分隔开，这是 print 默认的方式。</p><p>为了在字段值之间加入空格，你需要像下面这样添加（,）分隔符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $1, $2, $3; }&#39; tecmintinfo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TecMint.com is the</span></span></code></pre></div><p>很重要而且必须牢记的一点是，Awk 中 （$） 的使用和在 shell 脚本中不一样。</p><p>在 shell 脚本中 （$） 用于获取变量的值，而在 Awk 中 （$） 只用于获取一个字段的内容，而不能用于获取变量的值。</p><p><strong>事例2</strong>： 让我们再看一个使用多行文件 my_shoping.list 的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No	Item_Name		Unit_Price	Quantity	Price</span></span>
<span class="line"><span>1	Mouse			#20,000		   1		#20,000</span></span>
<span class="line"><span>2 	Monitor			#500,000	   1		#500,000</span></span>
<span class="line"><span>3	RAM_Chips		#150,000	   2		#300,000</span></span>
<span class="line"><span>4	Ethernet_Cables	        #30,000		   4		#120,000</span></span></code></pre></div><p>假设你只想打印购物清单中每个物品的 Unit_Price，你需要允许下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{print $2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name Unit_Price</span></span>
<span class="line"><span>Mouse #20,000</span></span>
<span class="line"><span>Monitor #500,000</span></span>
<span class="line"><span>RAM_Chips #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><p>Awk 也有一个 printf 命令，它能帮助你用更好的方式格式化输出，正如你可以看到上面的输出并不清晰。</p><p>使用 printf 格式化输出 Item_Name 和 Unit_Price：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;//{printf &quot;%-10s %s\\n&quot;,$2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name  Unit_Price</span></span>
<span class="line"><span>Mouse      #20,000</span></span>
<span class="line"><span>Monitor    #500,000</span></span>
<span class="line"><span>RAM_Chips  #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>使用 Awk 进行文本和字符串过滤时字段编辑功能非常重要，它能帮助你从列表中获取列的特定数据。同时需要记住 Awk 中 （$） 操作符和 shell 脚本中不一样。</p><p>我希望这篇文章能对你有所帮助，如果你需要获取其它信息或者有任何疑问，都可以在下面的评论框中告诉我们。</p><hr>`,26)),n("p",null,[s[7]||(s[7]=t("via: ",-1)),a(i,{href:"http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+%28Tecmint%3A+Linux+Howto%27s+Guide%29"},{default:e(()=>[...s[6]||(s[6]=[t("http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+(Tecmint%3A+Linux+Howto's+Guide)",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=t("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...s[8]||(s[8]=[t("Aaron Kili",-1)])]),_:1}),s[12]||(s[12]=t(" 译者：",-1)),a(i,{href:"https://github.com/ictlyh"},{default:e(()=>[...s[9]||(s[9]=[t("ictlyh",-1)])]),_:1}),s[13]||(s[13]=t(" 校对：",-1)),a(i,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:e(()=>[...s[10]||(s[10]=[t("校对者ID",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[t("Linux中国",-1)])]),_:1}),s[18]||(s[18]=t(" 荣誉推出",-1))])])}const A=p(u,[["render",k]]);export{C as __pageData,A as default};
